    faq_a_bag_examples_list: "नया बैग उदाहरणों के साथ आता है, जिन्हें बाकी चीज़ों की तरह बदला या हटाया जा सकता है: घर (ख़रीदारी, रेसिपी, इस हफ़्ते का खाना), परिवार (छोटे-छोटे पल, जन्मदिन की पार्टी की लिस्ट, गतिविधियाँ और क्लास), आइडिया (वीकेंड के आइडिया, श्रेणी के हिसाब से तोहफ़ों के आइडिया, और बचाए हुए पैसों का क्या करें) और यात्राएँ (जिन जगहों पर जाना है, यात्रा का सामान, होटल का सामान और विदेश की उड़ान की लिस्ट)। जो बैग पहले से था, उसमें सबसे नए उदाहरण एक बार, उसकी अपनी जेबों में जुड़ते हैं।",
    faq_q_bag_examples_list: "मेरे बैग में कौन-से उदाहरण होते हैं?",
    faq_a_nm_me1_guide: "Sky – New Me में आपका किरदार, अपने पहले रूप (Sky 1) में। पहली बार, जुड़ने के ठीक बाद, चारों ओर चमक बिखेरता हुआ रोशनी का एक पोर्टल खुलता है और उसमें से Sky उड़कर निकलता है, कुछ टैप में बताता है कि आगे क्या है, और फिर हर सवाल के पास रहता है: भोजन चुनते समय यह आपके साथ अपनी किताब में लिखता है, और इसकी सलाह पर टैप करने से एक और सलाह दिखती है। आख़िर में Sky आपके साथ जश्न मनाता है और एक छोटे टूर पर ले जाता है – और टूर ख़त्म होने पर, इसके पास आपके साथ एक और छोटा-सा पल होता है। अगर बीच में ही – सवालों या टूर के दौरान – बाहर निकल जाएँ, तो अगली बार Sky आपको देखकर खुश होता है और पूछता है कि क्या उसी जगह से आगे बढ़ें।",
    faq_q_nm_me1_guide: "New Me में प्रवेश के समय राह कौन दिखाता है?",
