    nm_m1_tip_ai: "कोई खाना सूची में नहीं है? बाद में \"बदलें\" में उसे अपने शब्दों में लिखा जा सकता है – और AI उसका हिसाब लगा लेगा। और अब, मिलकर चुनें कि हर दिन क्या खाना है।",
    nm_m1_tip_love: "और अगर कुछ पसंद न आए – तो उसे हमेशा AI से बदला जा सकता है। खाना कोई भी हो – अगर आपको पसंद है, तो वह मेन्यू में रहता है।",
    nm_m1_tip_rice: "मुझे चावल सबसे ज़्यादा पसंद है – यही मेरा आधार होगा, इसलिए मैं इसे चुनूँगा। मेरी सलाह है कि वही चुना जाए जो जाना-पहचाना और स्वादिष्ट हो।",
    faq_a_shop_basics: "जब खरीदारी सूची पूरी तरह खाली होती है – जैसे बिल्कुल शुरुआत में – तो शुरुआत के लिए एक बुनियादी सूची दिखती है: दूध, ब्रेड, अंडे और भी बहुत कुछ। किसी चीज़ पर एक टैप उसे सूची में जोड़ देता है, और “सभी जोड़ें” सब कुछ एक साथ जोड़ देता है। जैसे ही सूची में कुछ आ जाता है, यह गायब हो जाती है।",
    faq_q_shop_basics: "खाली खरीदारी सूची में बुनियादी सूची क्या है?",
