    room_genie_again_no: "अभी नहीं",
    room_genie_again_no_msg: "तो अब उन लक्ष्यों को पूरा करने का समय है जो आपने पहले से तय किए हैं। अगले लक्ष्य तक पहुँचने पर – वहाँ आपके लिए कुछ इंतज़ार कर रहा होगा ✨",
    room_genie_again_q: "फिर से यहाँ? ✨ क्या ज़िंदगी में कुछ और बदलने का मन है?",
    room_genie_again_yes: "हाँ",
    room_genie_bye: "फिर मिलेंगे",
    room_genie_rest: "जंगल की आत्मा अभी आराम कर रही है – कल फिर आइए ✨",
    faq_a_shop_holidays: "खरीदारी सूची में उपहार पर टैप करें: आपके देश (जो सेटिंग्स में चुना है) के त्योहार क्रम से, उनकी तारीखों के साथ दिखते हैं – तारीखें हर साल अपने-आप तय होती हैं। किसी त्योहार पर टैप करने से उसके लिए लोग जो खरीदते हैं, उसकी तैयार सूची खुलती है; सब कुछ चुना हुआ होता है (जो पहले से आपकी सूची में है, उसे छोड़कर), जो नहीं चाहिए उसका निशान हटाएँ और “सूची में जोड़ें” पर टैप करें। त्योहार से दो हफ़्ते पहले सूची के ऊपर एक छोटा कार्ड दिखता है; ✕ उसे अगले त्योहार तक छिपा देता है।",
    faq_q_shop_holidays: "“त्योहार के लिए क्या खरीदें” कैसे काम करता है?",
    shop_hol_add: "सूची में जोड़ें ({n})",
    shop_hol_added: "सूची में जोड़ा गया: {n}",
    shop_hol_btn: "त्योहार के लिए क्या खरीदें",
    shop_hol_items_title: "{holiday} – क्या खरीदें?",
    shop_hol_not_now: "अभी नहीं",
    faq_a_shop_delivery: "खरीदारी सूची में ट्रक पर टैप करें: चुनें कि डिलीवरी में क्या है (सब कुछ चुना हुआ होता है), वह कब पहुँचेगी – आज, कल या कोई और दिन – और किस समय (सुबह, दोपहर, शाम, या अपना समय चुनने के लिए “अन्य…”)। वे चीज़ें दिन और घंटों के साथ सूची के ऊपर “रास्ते में” कार्ड में चली जाती हैं। जब वह दिन आता है, तो मेरा दिन में “क्या डिलीवरी पहुँच गई?” दिखता है (और कार्ड पर “पहुँच गई?” होता है)। अगर सब कुछ पहुँच गया, तो वे “फिर से खरीदें” में चली जाती हैं। अगर कुछ कम है, तो जो नहीं पहुँचा उस पर टैप करें – वह सीधे सूची में लौट आता है।",
    faq_a_shop_departments: "सूची अपने-आप सुपरमार्केट के विभागों के हिसाब से लग जाती है – फल और सब्ज़ियां, ब्रेड, डेयरी और अंडे, मांस और मछली, किराना, फ्रोज़न, पेय पदार्थ, स्नैक्स, सफ़ाई, पर्सनल केयर, शिशु और पालतू जानवर – ताकि गलियारों में क्रम से घूमा जा सके। विभाग चीज़ के नाम से पहचाना जाता है। अगर कोई चीज़ गलत जगह चली गई, तो उस पर टैप करके उसका विभाग चुनें, या अपना विभाग लिखने के लिए “अन्य…” चुनें।",
    faq_a_shop_share_qty: "हाँ। हर चीज़ के पास, + एक और जोड़ता है (×2, ×3…) और − एक कम करता है। खरीदारी सूची के ऊपर शेयर बटन पूरी सूची को, विभागों के हिसाब से साफ़-सुथरे ढंग से लगाकर, WhatsApp, ईमेल या कॉपी के ज़रिए भेजता है।",
    faq_a_shop_two_buttons: "दोनों का मतलब है “खरीद लिया”। ✕ उस चीज़ के लिए है जो एक ही बार खरीदी जाती है – वह सूची से हट जाती है (और गलती होने की स्थिति के लिए 🗑️ संग्रह में इंतज़ार करती है)। ↺ उन चीज़ों के लिए है जो बार-बार खरीदी जाती हैं – वह सूची से हटकर “फिर से खरीदें” में इंतज़ार करती है: इसे सूची के सबसे नीचे कूड़ेदान के पास वाला छोटा ↺ बटन खोलता है, और वहाँ एक टैप किसी चीज़ को वापस सूची में डाल देता है। उसके अंदर “संपादित करें” से किसी चीज़ को उसमें से हटाया जा सकता है। कोई चीज़ जोड़ते समय, पहले खरीदी गई चीज़ें सुझाव के रूप में दिखती हैं, और अगर वह पहले से सूची में है तो दूसरी लाइन बनने के बजाय बस ×2 हो जाती है।",
