    faq_a_new_me_challenge_journal: "जब कोई चुनौती ख़त्म होती है – बड़ी, मिनी या हफ़्ते की चुनौती – तो जश्न में 📝 कैसा रहा? बटन होता है। यह चुनौती डायरी में एक पन्ना खोलता है: कैसा महसूस हुआ (पाँच चेहरे), किस चीज़ से मदद मिली, क्या मुश्किल था और इससे आगे क्या साथ ले जाएँ – इनमें से कुछ भी ज़रूरी नहीं है, और इसे बाद के लिए भी छोड़ा जा सकता है। डायरी जादुई बैकपैक में एक हीरा है: हर पूरी हुई चुनौती, उसकी तारीख़ और जो लिखा गया, सबसे नई सबसे ऊपर – किसी एक पर टैप करें और उसे पढ़ें, बदलें या शेयर करें (सिर्फ़ वही शेयर होता है जो पन्ने पर है)। पूरी हुई चुनौती को उपलब्धियों में एक मेडल भी मिलता है, “चुनौतियां जो मैंने पूरी कीं” के अंदर। चुनौती डायरी आम डायरी से अलग है।",
