    faq_a_ai_reminder_in_text: "हाँ – इसे कार्य के साथ ही लिख दें, जैसे “कल 17:00 बजे पार्सल लेना, एक घंटा पहले रिमाइंडर के साथ”। रिमाइंडर कार्य पर ही सेव होता है: एक घंटा पहले, आधा घंटा पहले, एक दिन पहले वगैरह, और बिना समय के “मुझे याद दिलाना” का मतलब है 10 मिनट पहले। टेक्स्ट में लिखे गए रिमाइंडर को उसी विंडो के रिमाइंडर फ़ील्ड पर प्राथमिकता मिलती है।",
    faq_q_ai_reminder_in_text: "क्या उसी अनुरोध में AI सहायक से रिमाइंडर भी माँगा जा सकता है?",
