    books_home_chip: "{title} · पृ. {page}",
    books_home_of: "कुल {total} में से",
    books_home_off_toast: "किताब होम स्क्रीन से हट गई",
    books_home_on_toast: "किताब होम स्क्रीन पर है 📖",
    books_home_pin: "होम स्क्रीन पर",
    books_home_q: "मैं किस पन्ने पर हूँ?",
    books_home_save: "सहेजें",
    faq_a_books_home_chip: "हाँ। पढ़ने का कोना में, जो किताब पढ़ी जा रही है उसके कार्ड पर, 📌 होम स्क्रीन पर को छुएँ। होम स्क्रीन पर अभिवादन के नीचे किताब और पन्ने वाला एक छोटा बटन दिखता है – उसे छुएँ, नया पन्ना नंबर लिखें और सहेजें, और प्रगति दर्ज हो जाती है (पढ़ने का कोना में भी)। 📌 को फिर छूने पर वह हट जाता है। कई किताबें एक साथ रह सकती हैं – हर एक के लिए एक बटन – और हर डिवाइस पर वही।",
    faq_a_new_me_week_challenge: "एक हफ़्ते की छोटी चुनौती, जिसे ख़ुद चुना जाता है। गलियारे में एक बड़ा कार्ड है: “इस हफ़्ते किस पर काम करना है?” – उसे छुएँ, कोई क्षेत्र चुनें (अपने साथ, दूसरों के साथ, सीखें और आगे बढ़ें, शांति, हिम्मत के छोटे क़दम, घर और दिनचर्या) और एक चुनौती, और तय करें कि वह कब शुरू हो। यही चुनौतियाँ “चुनौतियां” स्क्रीन में भी हैं, 🌱 व्यक्तिगत विकास के अंदर। हर दिन कार्ड पर ✓ लगाएँ (हफ़्ते में एक दिन की छूट), और हर पूरा होता हफ़्ता गुप्त दुनिया के लिए एक नई चाबी लाता है। “रोज़ 2 पन्ने पढ़ें” पढ़ने का कोना में दर्ज पन्नों से अपने आप चिह्नित हो जाती है। हफ़्ता पूरा होने पर 📌 रोज़ का काम बनाकर रखें उसे आपके चुने समय पर मेरी दिनचर्या में जोड़ देता है, हर दिन ✓ के साथ। एक समय में हफ़्ते की एक ही चुनौती चलती है; बड़ी और छोटी चुनौतियाँ उसके साथ-साथ चलती रहती हैं।",
    faq_a_room_genie: "समुद्र के सामने वाले बरामदे में अलादीन के चिराग़ को छूने पर जंगल की आत्मा निकलती है – और एक बातचीत शुरू होती है: आपकी इच्छा क्या है (ज़िंदगी में क्या बदलने का मन है), वह पूरी होने पर कैसा लगेगा, रास्ते में क्या मुश्किल है, और अभी की स्थिति को भलाई में कैसे बदला जा सकता है। फिर लगभग कितना समय लगेगा, एक छोटा पहला क़दम और दो और क़दम, और मुश्किल घड़ियों के लिए एक “अगर… तो…”। अंत में पूरी इच्छा क़दम दर क़दम सामने आती है, और उसे मेरे लक्ष्य में जोड़ा जा सकता है (क़दम रास्ते के चरण बन जाते हैं, चुने गए समय के हिसाब से तारीख़ के साथ; वहाँ सब कुछ बदला जा सकता है) या डायरी में सहेजा जा सकता है – और फिर आत्मा विदा लेती है। इनमें से कुछ न चुनने पर कुछ भी सहेजा नहीं जाता। दूसरी बार से, आत्मा पहले पूछती है कि क्या ज़िंदगी में कुछ और बदलने का मन है: हाँ – वही बातचीत; अभी नहीं – पहले से तय किए गए लक्ष्यों को पूरा करने की याद। आत्मा दिन में एक बार निकलती है: इच्छा सहेजे जाने के बाद (या “अभी नहीं” के बाद), वह कल तक आराम करती है। सवाल इच्छा को योजना में बदलने के एक जाने-माने तरीक़े पर आधारित हैं: इच्छा, नतीजा, बाधा और योजना।",
