    room_drawer_aria: "छोटी अलमारी",
    nm_me_choose: "चुनें",
    nm_me_on_screen: "स्क्रीन पर",
    faq_a_new_me_game: "New Me में खेल के बटन हमेशा एक ही जगह रहते हैं – गलियारे में, गुप्त कमरे में और जंगल में हर जगह; बस बीच की पेंटिंग बदलती है। ऊपर: सफ़र का दिन, चाबियाँ, सिलसिला और आज की ऊर्जा (प्लान में से कितना खाया जा चुका है), और उसके नीचे अगला मिशन – अपने समय पर अगला भोजन (टैप करने पर खुलता है, ✓ खा लिया के साथ)। एक तरफ़: पूरा दिन, चुनौतियां और मेरा सफ़र, और उनके पास हफ़्ते की चुनौती – उसके 7 दिन और आज के लिए ✓। नीचे: जादुई बैकपैक (पूरा New Me – दुनिया का नक्शा, मेरा सफ़र, खरीदारी सूची, उपलब्धियां, चुनौती डायरी, शरीर के माप, प्रगति की तस्वीरें, मासिक कैलेंडर, दैनिक तालिका, रिमाइंडर, मेन्यू PDF और सेटिंग्स; यह अपनी अलग स्क्रीन के रूप में खुलता है)। दुनिया का नक्शा, जो बैकपैक में सबसे पहले है, जंगल की हर जगह दिखाता है – किसी जगह पर टैप करें और वहाँ पहुँचें; बंद जगह पर दिखता है कि उसके लिए कितनी चाबियाँ चाहिए। Sky जंगल की पगडंडी पर आपका किरदार है: यह Sky 1 के रूप में शुरू होता है, कुछ चुनौतियों (4 चाबियाँ) के बाद बढ़कर Sky 2 बनता है और आख़िर के पास (9 चाबियाँ) Sky 3 – ऐसे नए रूप के साथ जिसे होते हुए देखा जा सकता है। सारे पड़ाव देखने के लिए Sky पर टैप करें – जो पड़ाव पहले ही मिल चुका है उसे दोबारा चुना जा सकता है, यानी पिछला पड़ाव लौट सकता है। Sky तैरता है – इसे उंगली या माउस से खींचा जाता है, और जिस प्रवेश को यह छूता है वह खुल जाता है (बंद प्रवेश पर दिखता है कि कितनी चाबियां कम हैं)। Sky हर कमरे और हर जगह में भी साथ आता है और जहाँ आप उसे छोड़ें, वहीं तैरता रहता है: इसे कहीं भी खींचें, और इसके नीचे के चमकते घेरे को खींचकर इसे पूरा घुमाएँ; यह उसी दिशा में मुँह करता है जिधर चलता है (कंप्यूटर पर: तीर इसे चलाते हैं, Q और E इसे घुमाते हैं)। गलियारे में, ऊपरी बार के नीचे का छोटा 🏠 होम स्क्रीन पर वापस ले जाता है; हर कमरे और हर जगह में, उसी कोने का बटन गलियारे में वापस ले जाता है।",
    faq_q_new_me_game: "खेल के बटन, दुनिया का नक्शा और Sky कैसे काम करते हैं?",
