    faq_a_new_me_menu_build: "पहले प्रश्नावली पूछती है कि दिन में कौन-से भोजन और कब होते हैं (2 भोजन + एक नाश्ता, 2 भोजन + हल्का रात का खाना, या दोनों), और क्या शाम को कुछ होता है – खाने को या पीने को, क्या और किस समय। “2 भोजन + एक नाश्ता” में भोजन हैं दोपहर का भोजन (11:30) और रात का खाना (19:00), और स्नैक 16:00 पर। फिर उन भोजनों के सारे विकल्प दिखते हैं। हर भोजन के लिए 2 पसंदीदा तक चुनें – मेन्यू में लिखा होगा “यह या वह”। कुछ विकल्पों में (पीटा और स्प्रेड, कॉर्न फ़्लेक्स और दूध, कुछ हल्का) पसंद की 3 चीज़ें तक चुनी जा सकती हैं, हर एक अपनी मात्रा में, और मेन्यू में लिखा होगा “यह या वह या वह”; कैलोरी चुनी गई चीज़ों के हिसाब से होती है। कॉफ़ी और पेय भी ऐसे ही चुने जाते हैं। हर चुनाव संतुलित होता है, इसलिए दिन का जोड़ ठीक 1,300 या 1,500 रहता है। कभी भी बदलने के लिए: ⚙️ सेटिंग्स → 🍽️ अपना मेन्यू बनाएं, या भोजन के कार्ड पर “अपनी पसंद की 3 तक चुनें”।",
