    faq_a_myday_water_toggle: "हां। 'मेरा दिन' में पानी का गिलास (एक और गिलास के लिए + के साथ) डिफ़ॉल्ट रूप से दिखता है। इसे छिपाने के लिए सेटिंग्स > पर्सनलाइज़ेशन और कैलेंडर में \"'मेरा दिन' में पानी दिखाएं\" बंद करें। कुछ भी डिलीट नहीं होता – पानी ट्रैकिंग चलती रहती है, और स्विच फिर से चालू करने पर गिलास वापस आ जाता है।",
    faq_q_myday_water_toggle: "क्या 'मेरा दिन' में पानी छिपाया जा सकता है?",
    myday_water_toggle_label: "'मेरा दिन' में पानी दिखाएं",
    faq_a_routine_newme_sync: "New Me होने पर 'मेरी दिनचर्या' के ⚙️ में 'New Me के साथ सिंक' स्विच होता है। चालू होने पर (डिफ़ॉल्ट) आज के New Me भोजन 'मेरा दिन' और 'मेरी दिनचर्या' में दिखते हैं – दिनचर्या के छिपाए गए भोजनों की जगह। बंद करने पर New Me के भोजन दोनों जगहों से हट जाते हैं और दिनचर्या बिल्कुल पहले जैसी हो जाती है। कुछ भी मिटता नहीं – दोबारा चालू करने पर सब लौट आता है और पूछा जाता है कि दिनचर्या के कौन से भोजन छिपाने हैं।",
    faq_q_routine_newme_sync: "New Me का 'मेरी दिनचर्या' और 'मेरा दिन' के साथ सिंक कैसे चालू या बंद करें?",
