    faq_a_food_list_languages: "बिल्ट-इन खाने की सूची इज़राइली खानों और उनके हिब्रू नामों से शुरू हुई थी। बाकी सभी भाषाओं में हर खाद्य पदार्थ अपने अंग्रेज़ी नाम से दिखता है, और खोज हर उस अंग्रेज़ी नाम से ढूंढती है जो उसे पता है (जैसे 'broth' से Clear soup मिलता है); जिन खाद्य पदार्थों का सिर्फ़ हिब्रू नाम है, वे वहाँ नहीं दिखते। जो सूची में नहीं है, उसे बस अपने शब्दों में लिखें – AI अनुमान हर भाषा में काम करता है।",
    faq_q_food_list_languages: "मेरी भाषा में खाने की सूची में अंग्रेज़ी नाम और कम खाद्य पदार्थ क्यों दिखते हैं?",
    settings_copyright_line: "© 2026 सर्वाधिकार सुरक्षित। ऐप डेवलपर: eden zabari",
    workout_ready_replace_btn: "बदलें",
    faq_a_sport_workout_ai: "\"मेरे वर्कआउट\" → ⋯ → \"AI से प्लान\" (और टेबल खाली हो तो तैयार प्लान के पास वाली टाइल पर भी)। कुछ टैप से जवाब दें – हफ़्ते में कितनी बार, कब, जगह, स्तर और लक्ष्य, लगभग सभी में \"अन्य\" भी है – और चाहें तो एक खुली लाइन जोड़ें, जैसे संवेदनशील घुटना या गर्मियों तक 5 किमी दौड़ना। AI पूरा हफ़्ता बनाता है: वर्कआउट के प्रकार, दिन, समय, अवधि, तीव्रता, एक्सरसाइज़ और आराम के दिन। सेव होने से पहले प्रीव्यू दिखता है: \"मेरी टेबल में डालें\" (टेबल की जगह या उसके साथ), \"दूसरा सुझाव\" (3 बार तक) या \"जवाब बदलें\"। प्लान जानबूझकर संतुलित रखा जाता है, और दर्द या चोट का ज़िक्र करने पर हल्के विकल्प और किसी विशेषज्ञ से सलाह लेने का सुझाव मिलता है। यह शेड्यूल और दिनचर्या वाले AI की ही सीमा इस्तेमाल करता है: 5 बार मुफ़्त, और प्रीमियम में महीने में 60 बार।",
    faq_q_sport_workout_ai: "AI से वर्कआउट प्लान कैसे बनाएँ?",
