    workout_ai_working: "आपका प्लान बन रहा है…",
    faq_a_sport_workout_jar: "हर तरह के वर्कआउट का अपना रंगीन सितारा है – दौड़ गुलाबी, पैदल चलना हरा, तैराकी नीला वगैरह। इस हफ़्ते दर्ज किया गया हर वर्कआउट, टेबल से या अलग से, अपना सितारा \"मेरे वर्कआउट\" में ऊपर वाले जार में डाल देता है, और जार साप्ताहिक लक्ष्य तक भरता जाता है (लक्ष्य बदलने के लिए उस पर टैप करें)। लक्ष्य पूरा होने पर जार चमक उठता है। पास वाला छोटा जार गिनता है कि लगातार कितने हफ़्ते वह भरा।",
    faq_q_sport_workout_jar: "\"मेरे वर्कआउट\" में रंगीन सितारे और जार क्या हैं?",
    faq_a_sport_workout_gcal: "हाँ – ⋯ → Google कैलेंडर में (सेटिंग्स में Google कैलेंडर जोड़ने के बाद)। समय वाला हर वर्कआउट उसके दिनों पर हर हफ़्ते दोहराने वाला इवेंट बन जाता है, और ऐप में बदलाव उसमें भी हो जाते हैं। रिमाइंडर सिर्फ़ ऐप से आते हैं, इसलिए Google अपने रिमाइंडर नहीं जोड़ता, और वर्कआउट ऐप में कभी दो बार नहीं दिखते। फिर से छूने पर Google कैलेंडर से सिर्फ़ वर्कआउट हटते हैं।",
    faq_q_sport_workout_gcal: "क्या मेरे वर्कआउट Google कैलेंडर में दिख सकते हैं?",
    workout_gcal_btn: "Google कैलेंडर",
    workout_gcal_error: "Google कैलेंडर अपडेट नहीं हो सका – अगले बदलाव पर फिर कोशिश होगी",
    workout_gcal_not_connected: "पहले सेटिंग्स में Google कैलेंडर जोड़ें",
    workout_gcal_off_toast: "वर्कआउट Google कैलेंडर से हटा दिए गए",
    workout_gcal_on_toast: "आपके वर्कआउट Google कैलेंडर में आ गए",
    faq_a_sport_workout_reminder: "हाँ – वर्कआउट में रिमाइंडर: 10 मिनट, 30 मिनट या एक घंटा पहले, या अपनी पसंद का समय (वर्कआउट का समय होना चाहिए)। यह बाकी रिमाइंडर की तरह बजता है, एक बार और एक ही जगह: ऐप खुला हो तो ऐप में, वरना फ़ोन पर। \"हो गया\" वर्कआउट को इतिहास में दर्ज करता है, और \"अभी नहीं\" 5 मिनट बाद फिर याद दिलाता है।",
    faq_q_sport_workout_reminder: "क्या वर्कआउट से पहले रिमाइंडर मिल सकता है?",
    workout_reminder_30min: "30 मिनट पहले",
    workout_reminder_label: "रिमाइंडर",
    workout_reminder_need_time: "रिमाइंडर पाने के लिए समय जोड़ें",
    faq_a_sport_workout_share: "⋯ → शेयर करें में हफ़्ता आपकी थीम के रंगों में एक काँच जैसी तस्वीर बन जाता है, ऐप के एक हल्के लिंक के साथ (फ़ोन पर सीधे शेयर मेन्यू खुलता है, कंप्यूटर पर तस्वीर सहेज ली जाती है)। ⋯ → प्रिंट के लिए PDF पूरे हफ़्ते का साफ़ पेज खोलता है, हर वर्कआउट और एक्सरसाइज़ के पास टिक करने का बॉक्स होता है – \"PDF के रूप में सहेजें\" चुनें या प्रिंट करें। प्लान सेटिंग्स की डेटा रिपोर्ट में स्पोर्ट वाले हिस्से में भी दिखता है।",
    faq_q_sport_workout_share: "अपने हफ़्ते के वर्कआउट कैसे शेयर या प्रिंट करूँ?",
    share_image_saved: "तस्वीर सहेज ली गई – अब इसे जोड़ सकते हैं",
    share_save_image: "तस्वीर सहेजें",
    workout_pdf_btn: "प्रिंट के लिए PDF",
    workout_share_btn: "शेयर करें",
    faq_a_sport_workout_board: "⋯ → साप्ताहिक बोर्ड में हर दिन एक कॉलम है: वर्कआउट को दूसरे दिन पर खींचें (फ़ोन पर पहले देर तक दबाएँ)। वर्कआउट में \"मेरी दिनचर्या में भी\" उसे उसके समय और दिनों पर आपकी दिनचर्या में डाल देता है, और बदलाव दोनों तरफ़ से एक जैसे रहते हैं; मेरी दिनचर्या के किसी आइटम से \"मेरे वर्कआउट में जोड़ें\" उल्टा करता है। किसी भी जगह ✓ दोनों में गिना जाता है, और मेरा दिन में यह एक ही बार दिखता है – पानी के पास वाली चिप में।",
    faq_q_sport_workout_board: "वर्कआउट को दूसरे दिन कैसे ले जाऊँ, और मेरी दिनचर्या से कैसे जोड़ूँ?",
    routine_in_workouts_btn: "मेरे वर्कआउट में खोलें",
