    workout_view_board: "साप्ताहिक बोर्ड",
    workout_view_timeline: "टाइमलाइन",
    faq_a_sport_workout_plan: "वर्कआउट ट्रैकिंग में, \"मेरे वर्कआउट\" के नीचे: + वर्कआउट – प्रकार, दिन, समय, अवधि, तीव्रता और जगह (\"अन्य\" भी)। स्ट्रेंथ, फ़ंक्शनल और तैराकी वर्कआउट में एक्सरसाइज़ की सूची जोड़ी जा सकती है, और \"आराम\" आराम का दिन चिह्नित करता है। किसी तैयार प्लान से भी शुरू कर सकते हैं। आज का वर्कआउट बड़ा दिखता है और नीचे पूरा हफ़्ता; ✓ उसे तीव्रता के साथ वर्कआउट इतिहास में दर्ज करता है। ⋯ में साप्ताहिक लक्ष्य तय होता है (वर्कआउट या मिनट) – हर किया गया वर्कआउट अपना सितारा जार में डाल देता है।",
    faq_a_sport_workout_today: "मेरा दिन में, पानी के पास एक छोटी चिप आज का वर्कआउट दिखाती है – छूने पर विवरण, ✓ और ▶ खुलते हैं। ▶ टाइमर शुरू करता है जो होम स्क्रीन की चिप में भी चलता रहता है, और \"समाप्त\" वर्कआउट को असली समय के साथ दर्ज करता है। अगर New Me में \"हलचल के दो हफ़्ते\" चुनौती चल रही है, तो दर्ज वर्कआउट उसमें अपने आप गिना जाता है।",
    faq_q_sport_workout_plan: "अपने हफ़्ते के वर्कआउट की योजना कैसे बनाऊँ?",
