    faq_a_new_me_ai_menu: "मेन्यू से पहले प्रश्नावली पूछती है कि कौन-से भोजन और कब होते हैं (2 भोजन + एक नाश्ता, 2 भोजन + हल्का रात का खाना, या दोनों), क्या शाम को कुछ छोटा खाया जाता है और किस समय, क्या नहीं खाया जाता, और कॉफ़ी या चाय कैसे पी जाती है। फिर AI हर भोजन के लिए 3 विकल्प बनाता है – हर एक दिन में उस भोजन के हिस्से के बराबर, ताकि दिन का जोड़ अब भी ठीक 1,300 या 1,500 रहे – और पेय के सुझाव भी, जो आपके तय पेय के रूप में सेव होते हैं। हर भोजन के लिए 2 पसंदीदा तक चुनें; मूल मेन्यू के विकल्प ठीक नीचे हैं, और 🔄 बदलें में वे आपके निजी मेन्यू के बाद आते हैं। 🔄 दूसरे विकल्प नया सेट बनाता है (हर प्रश्नावली में 3 बार)। जवाब बदलने या कभी भी नया मेन्यू बनाने के लिए: ⚙️ सेटिंग्स → ✨ निजी मेन्यू (AI)।",
