    room_back_to_shelf: "शेल्फ़ पर",
    faq_a_new_me_day_total: "हर दिन ठीक प्लान के बराबर होता है: भोजन, दिन भर कॉफ़ी और पेय के लिए लगभग 150 कैलोरी, और शाम के लिए जो चुना गया – कुछ हल्का खाने को या कुछ पीने को। शाम के लिए अपनी पसंद की 3 तक चुनें (जैसे एक केला, एक दही या डार्क चॉकलेट के 2 टुकड़े; या हर्बल चाय, थोड़े दूध वाली चाय या गुनगुना दूध), और उनकी कैलोरी भोजन से घटती है। हर चुनाव अपने-आप संतुलित होता है: छोटा या बड़ा विकल्प, हटाया गया भोजन, छोटा नाश्ता और उसके साथ आने वाला छोटा भोजन, या शाम – अंतर भोजनों में जोड़ा या उनसे घटाया जाता है, हर एक में उसके आकार के हिसाब से, और हर भोजन के नीचे लिखा होता है कितना (+ या −) और क्या जोड़ें या छोड़ें। जो भोजन पहले से टिक हो चुका है, वह वैसा ही रहता है जैसा दर्ज हुआ। प्रश्नावली में हर भोजन के पास उसका सुधार दिखता है, और एक छोटा बॉक्स भोजन, पेय, शाम और कुल दिखाता है। उस दिन कुछ और खाने का मन है? कुल कैलोरी उतनी ही या कम रखें।",
