    books_quotes_chip: "उद्धरण",
    faq_a_book_quotes: "गुप्त कमरे की शेल्फ़ पर (उद्धरण), या पढ़ने का कोना में छोटे 💬 उद्धरण चिप से – दोनों एक ही सूची है। \"+ उद्धरण\" पर टैप करें, पंक्ति लिखें और पढ़ने का कोना से किताब चुनें, या \"✏️ अन्य\" से कोई और नाम लिखें; लेखक वैकल्पिक है। ✏️ उद्धरण बदलता है और 🗑️ हटाता है। उद्धरण बुकमार्क हैं जिन्हें स्वाइप करके देखते हैं – ऊपर 🎨 से फ़ोटो या कार्डों की दीवार पर बदलें।",
    faq_a_room_wish_jar: "गुप्त कमरे की शेल्फ़ पर सपनों के लिए काँच का एक जार है। ऊपर वाली शेल्फ़ पर छोटे जार पर टैप करें (या शेल्फ़ > इच्छाओं का जार) और लिखें कि अपनी ज़िंदगी कैसी चाहिए – जितना चाहें बड़ा, कोई सही-गलत नहीं। हर इच्छा एक पर्ची में मुड़कर जार में गिरती है। “एक पर्ची निकालें” कोई भी एक पर्ची खोलता है, और हर पर्ची को अलग से भी खोला जा सकता है। एक ही इच्छा को दूसरी बार खोलने से, उसे लक्ष्य बनाकर छोटे कदमों में बाँटा जा सकता है। हफ़्ते में एक बार आपकी किसी इच्छा वाली पर्ची धीरे से सामने आती है – बिना दबाव, बस यह याद दिलाने के लिए कि मंज़िल किस ओर है।",
