    faq_a_saved_meals_page: "सहेजे गए भोजन का अपना एक पेज है: पोषण और मेट्रिक्स > ⭐ सहेजे गए भोजन (या मेनू में ⭐)। ऊपर की खोज नाम या सामग्री से भोजन ढूँढती है, \"हाल में इस्तेमाल\" में वह दिखता है जो आपने हाल ही में जोड़ा, और टैब (नाश्ता, दोपहर का खाना, रात का खाना, सूप…) दिन के हर समय को दिखाते हैं। \"+ आज\" भोजन को आज के दैनिक भोजन ट्रैकर में अगली ख़ाली जगह पर जोड़ देता है। किसी भोजन को बदलने या हटाने के लिए उस पर टैप करें, और ऊपर का ＋ नया भोजन जोड़ता है।",
