    faq_a_notes_sticky_look: "नोट्स कांच के कार्डों की एक छोटी सूची हैं – नोट्स के ऊपर 🎨 सारे नोट्स का रूप बदलता है: सूची, ऊपर के दिनों वाले बटन और वह विंडो जिसमें नोट लिखा जाता है – कांच, साफ़ सूची, इंडेक्स कार्ड या वाशी टेप। खींचा जा रहा नोट ठीक अपना ही रूप और रंग बनाए रखता है। किसी नोट का टेक्स्ट टैप करके उसे खोलें – वहाँ उसे बदला जा सकता है, उसके रंग बदले जा सकते हैं और देखा जा सकता है कि वह आख़िरी बार कब लिखा गया था। काम हो जाने पर ○ टैप करें, और × उसे संग्रह में भेज देता है (सूची के नीचे 🗑️ से वापस लाया जा सकता है)। क्रम बदलने, “बाद में” के नीचे ले जाने या ऊपर किसी दिन पर रखने के लिए ⠿ से खींचें। ! किसी नोट को अर्जेंट चिह्नित करता है – वह धीरे से ऊपर की पहली पंक्तियों में चला जाता है, एक छोटे “अर्जेंट” टैग के साथ; फिर से टैप करने पर निशान हट जाता है।",
    faq_q_notes_sticky_look: "नोट कैसे खोलें, बदलें या हटाएँ?",
    note_to_archive_btn: "संग्रह में भेजें",
    faq_a_routine_clash: "अगर उसी समय उन्हीं दिनों में पहले से कोई चीज़ है, तो दो विकल्प मिलते हैं: \"बदलें\" – नई चीज़ उस समय पर आ जाती है और पहले वाली के लिए दूसरा समय चुनते हैं (किसी मौजूदा चीज़ को बदलते समय उसका पिछला समय सुझाया जाता है, ताकि दोनों बस आपस में बदल जाएँ), या \"दोनों\" – दोनों एक ही समय पर रहती हैं, एक के नीचे दूसरी। अगर दिन अलग हैं (जैसे एक रवि–गुरु और दूसरी शुक्रवार), तो कुछ नहीं पूछा जाता।",
    faq_q_routine_clash: "अगर दिनचर्या में कोई चीज़ ऐसे समय पर रखूँ जो पहले से भरा है, तो क्या होता है?",
    routine_clash_both: "✌️ दोनों – दोनों {time} पर",
