    faq_a_new_me_coffee: "आज के मेन्यू के नीचे एक छोटा सारांश है: आज के सारे भोजन कुल कितनी कैलोरी के हैं, कॉफ़ी और पेय के लिए कितना बाकी है, और चुनी गई कॉफ़ी और पेयों के बटन – एक टैप से वह पेय में जुड़ जाता है। बटनों के नीचे \"अपनी पसंद की 3 तक चुनें\" में (और प्रश्नावली में) चुनें कि क्या दिखे: पानी / सोडा वाटर, हर्बल चाय, डाइट ड्रिंक, ब्लैक / अमेरिकानो (~5), थोड़े दूध वाली चाय (~25), पानी वाली कॉफ़ी 100 मि.ली. तक दूध या प्लांट मिल्क के साथ (~50), हल्की हॉट चॉकलेट, गुनगुना दूध या सामान्य कॉफ़ी / लाटे (~120)।",
