    faq_a_recipe_examples: "अपनी रेसिपी के नीचे उदाहरण रेसिपी हैं: नाश्ता, सलाद, सूप, मुख्य व्यंजन, साइड डिश, स्नैक, मिठाई और वीगन व्यंजन। हर एक में बनाने का समय, प्रति सर्विंग कैलोरी और एक सर्विंग कितने ग्राम की है, यह लिखा है। रेसिपी खोलने के लिए उस पर टैप करें, और \"मेरी रेसिपी में सेव करें\" आपकी अपनी कॉपी बनाता है, जिसे बदला जा सकता है। श्रेणी वाले चिप छाँटते हैं, और उसी चिप पर दोबारा टैप करने से सब दिखता है।",
    faq_a_recipe_grams: "रेसिपी के अंदर, कैलोरी के पास लिखा होता है \"1 सर्विंग ≈ X ग्राम\"। अपनी रेसिपी में, रेसिपी फ़ॉर्म में \"प्रति सर्विंग ग्राम\" (और चाहें तो बनाने का समय) भरें: दोनों ज़रूरी नहीं हैं, और समय रेसिपी की रंगीन पट्टी पर दिखता है।",
