    faq_a_recipe_scan_multi: "हाँ। \"रेसिपी जोड़ें\" में 📷 पर टैप करें और एक या कई फ़ोटो चुनें (6 तक; PDF भी चलेगा)। हर फ़ोटो एक छोटी सूची में दिखती है, जहाँ चुनें कि उसमें क्या है: सब, सामग्री या तरीका, और \"➕ एक और फ़ोटो\" से और जोड़ें। फिर \"✨ रेसिपी स्कैन करें\" पर टैप करें: AI सब कुछ क्रम से, बिना दोहराए, एक ही रेसिपी में जोड़ देता है, और यह एक ही स्कैन गिना जाता है। AI सहायक के 📷 फ़ोटो से चुनी गई कई तस्वीरें भी यहीं खुलती हैं।",
    faq_q_recipe_scan_multi: "क्या कई फ़ोटो से एक ही रेसिपी स्कैन हो सकती है, जैसे सामग्री और बनाने का तरीका अलग-अलग, या दो पन्ने?",
