    faq_a_note_written_at: "नोट खोलने के लिए उसके टेक्स्ट पर टैप करें। अंदर, टेक्स्ट के नीचे, दिखता है कि वह आख़िरी बार कब लिखा गया था, सही तारीख़ और समय के साथ। यह सिर्फ़ टेक्स्ट बदलने पर अपडेट होता है: आर्काइव करना और वापस लाना, ✓ लगाना, रंग या नोट को खिसकाना इसे नहीं बदलते।",
