    faq_a_new_me_month: "जादुई बैकपैक → मासिक कैलेंडर में: हर दिन इस हिसाब से रंगा होता है कि कितने भोजन टिक हुए, ‹ › तीर महीनों के बीच ले जाते हैं, और कैलेंडर के नीचे महीने की रोज़ की औसत कैलोरी लिखी होती है। किसी दिन पर टैप करने से दिखता है कि उस दिन कितने भोजन टिक हुए और कितनी कैलोरी खाई गईं।",
