    faq_a_new_me_small_breakfast: "एक हल्का नाश्ता (लगभग 170 कैलोरी): स्प्रेड या चीज़ के साथ एक स्पेल्ट पीटा (100 कैलोरी तक), साथ में एक सब्ज़ी – अपनी पसंद की 3 तक चुनें, जैसे 1 छोटा चम्मच चॉकलेट स्प्रेड, 1 छोटा चम्मच पीनट बटर या हार्ड चीज़ का एक स्लाइस (22% तक)। यह छोटा है, इसलिए इसके साथ किसी और समय “और एक छोटा भोजन” आता है (डेढ़ घंटे बाद, जैसे 11:30 → 13:00 – कोई और समय भी चुना जा सकता है): एक और पीटा और स्प्रेड, प्रोटीन दही और फल, राइस केक और चीज़, सीरियल और दूध या आधा पीटा और अंडे – लगभग 200 कैलोरी तक, अपने ✓ के साथ। जो फिर भी बचता है वह बाकी भोजनों में बँट जाता है, और हर भोजन दिखाता है कि उसमें कितना जुड़ा, इसलिए दिन का कुल योग प्लान जितना ही रहता है। इसे प्रश्नावली में चुनें, या 🔄 से सिर्फ़ आज के लिए इस पर बदलें – जैसे जब नाश्ता देर से हो।",
