    faq_a_ai_icon: "हाँ – सेटिंग्स > दिखावट और डिस्प्ले में। मुलायम बुलबुला डिफ़ॉल्ट है, और Premium के साथ तैरता दिमाग या रोबोट भी चुना जा सकता है।",
    faq_a_new_me_favorites: "हाँ। प्रश्नावली में (और सेटिंग्स से उसे दोबारा भरते समय भी) हर भोजन के लिए 2 विकल्प तक चुने जा सकते हैं। पहला मेनू में दिखता है, और उसके नीचे दूसरे के लिए “या” वाली पंक्ति – उस पर टैप करने से सिर्फ़ आज के लिए वही हो जाता है। और अगर नाश्ता समय पर नहीं खाया गया, तो “⏰ बाद में” उसे दिन में बाद के समय पर ले जाता है, कैलोरी बदले बिना।",
    faq_a_theme_mode: "कुछ खास थीम डार्क में सबसे सुंदर लगती हैं – वॉटरकलर, ऑरोरा, बार्बी और दोनों स्पार्कल थीम – इसलिए इनमें से कोई चुनने पर ऐप डार्क मोड में चला जाता है, और कोई भी दूसरी थीम (रॉकेट भी) चुनने पर लाइट में। काली और गहरी स्लेटी थीम डार्क ही रहती हैं। बाद में कभी भी मेनू के 🌙 या सेटिंग्स के लाइट मोड से बदला जा सकता है।",
    faq_a_water_month: "पानी ट्रैकिंग में। आज के रिकॉर्ड की हर एंट्री के साथ वह समय दिखता है जब उसे जोड़ा गया, और \"मासिक तालिका\" पूरा महीना खोलती है: हर दिन में दिखता है कि कितने लीटर पिए गए (रोज़ का लक्ष्य पूरा होने पर ✓), और किसी दिन पर टैप करने से उसकी एंट्री समय के साथ दिखती हैं।",
