    menu_night_mode: "नाइट मोड",
    faq_a_secret_room_yoga: "जंगल की पगडंडी के आख़िर में एक चमकता द्वार है, और उसके पीछे, एक झरने के पास, जंगल के जीव – लूमी, पफ़ी, निक्सी और स्पार्कलेट – अर्धवृत्त में अपनी-अपनी चटाइयों पर बैठे हैं, और योग शिक्षिका फ़्लोरा उनके सामने पत्थर पर बिछी अकेली चटाई पर बैठी हैं। फ़्लोरा पर टैप करें: वह आँखें खोलती हैं, सब कुछ पास आ जाता है, और बातचीत धीरे-धीरे, पढ़ने का समय देते हुए शुरू होती है – फ़्लोरा पूछती हैं कि सब कैसे हैं, हर जीव अपने नाम से जवाब देता है (हर पंक्ति के पास बोलने वाले की एक छोटी तस्वीर होती है), और फिर वह आपसे पूछती हैं कि अपने करीबी लोगों के साथ कैसा महसूस होता है। बातचीत आपके जवाबों के हिसाब से आगे बढ़ती है – अच्छे लोग, कोई मुश्किल इंसान, या थोड़ा अकेलापन। हर रास्ता एक छोटे मिशन (जिसे सीधे 'मेरा दिन' में जोड़ा जा सकता है; जब मिशन कुछ लिखने का हो, तो लिखने की जगह होती है, और लिखा हुआ जादुई डायरी में सहेजा जाता है) और साथ में तीन साँसों वाले एक आसन पर ख़त्म होता है। ↩ एक कदम पीछे ले जाता है और ✦ नई बातचीत शुरू करता है। अगली चाबी झरना खोलती है: पत्थर पर बैठते ही सब कुछ छिप जाता है और सिर्फ़ पानी की आवाज़ रह जाती है। तालाब पर झुकते ही पानी से एक सवाल उभरता है – आपका असली रूप आज क्या करता? – और जवाब 'मेरा दिन' में एक छोटा काम बन जाता है। यह एक प्यारा पल है, किसी विशेषज्ञ से बात करने का विकल्प नहीं।",
