    nm_time_hour: "घंटा",
    nm_time_minutes: "मिनट",
    routine_time_taken: "इस समय पर पहले से कुछ है: {title}",
    faq_a_new_me_times: "शुरुआत की प्रश्नावली में, और कभी भी New Me की सेटिंग्स → \"खाने का समय\" में। अगर दिनचर्या में पहले से खाने के समय हैं, तो वे वहीं से लिए जाते हैं – और दिनचर्या के भोजन छिपाकर उनकी जगह New Me के भोजन दिखाए जा सकते हैं। अगर नहीं हैं, तो चुनें कि दिन में कितनी बार भोजन (2 भोजन + एक नाश्ता / 2 भोजन + हल्का रात का खाना / 2 भोजन + एक नाश्ता + हल्का रात का खाना) और हर एक कब। \"2 भोजन + एक नाश्ता\" में ये हैं 11:30 पर दोपहर का भोजन, 16:00 पर स्नैक और 19:00 पर रात का खाना (हर एक बदला जा सकता है)। यही हर जगह खाने का समय है: गलियारे में, \"मेरा दिन\" में, \"मेरी दिनचर्या\" में और रिमाइंडर में। कुछ भी चुनें, दिन की कैलोरी वही रहती है: जो हटाया जाता है वह बाकी भोजनों में बँट जाता है।",
