    faq_a_routine_exact_time: "हाँ। जब AI को सटीक समय के साथ दिनचर्या बताई जाती है (जैसे \"16:10 ट्रेडिंग\"), तो वह बिल्कुल वैसे ही सहेजी जाती है – पूरे घंटे में गोल नहीं की जाती। दिनचर्या में जो कुछ लिखा है, वह हमेशा बोर्ड पर दिखता है, भले ही उसका घंटा घंटों की सेटिंग में चुना न गया हो, और जिस घंटे में कुछ लिखा हो उसे हटाने से पहले पूछा जाता है। समय हाथ से भी बदला जा सकता है: आइटम की विंडो में समय को छुएँ और घंटा व मिनट चुनें।",
