    faq_a_secret_room_diary: "सिर्फ़ आप। डायरी के पन्ने आपके खाते में सहेजे जाते हैं, इसलिए वे हर डिवाइस पर रहते हैं और कोई और उन्हें नहीं देख सकता। गुप्त कमरे में मेज़ पर रखी जादुई डायरी इसे खोलती है, और संगीत वाले कोने की डायरी भी। नए पन्ने के नीचे एक मुड़ा हुआ मासिक कैलेंडर है: जिस दिन कोई पन्ना है उस पर एक बिंदु होता है, और किसी दिन को छूने पर उसके पन्ने खुलते हैं – वहाँ पन्ना हटाया भी जा सकता है। डायरी खुल जाने के बाद उसे मुख्य मेनू में भी जोड़ा जा सकता है – डायरी के अंदर या New Me की सेटिंग्स में मौजूद स्विच से।",
    faq_a_secret_room_places: "जंगल के द्वार पर हर प्रवेश अपनी चाबी से खुलता है। उनके पीछे: समुद्र के सामने वाला बरामदा (छोटी मेज़ पर अलादीन का चिराग़ – छूते ही उसमें से जादुई धुंध में जंगल की एक आत्मा निकलती है, चारों ओर घूमती है और आपकी इच्छा के बारे में बातचीत शुरू करती है – देखें “चिराग़ का जिन्न क्या करता है?”), गिटार और डायरी (गिटार एक छोटी, शांत धुन बजाता है और अपने आप रुक जाता है, और पेड़ पर टँगे तीनों रिकॉर्ड में से हर एक अपनी जादुई धुन बजाता है – दोबारा छूने पर धुन रुक जाती है – और ठूँठ पर रखी डायरी लिखने के लिए है), साँस लेने का कमरा (सूर्यास्त के समय एक शांत झील – पानी पर कमल की लालटेन तैरती है: उसे छुएँ, मन्नत लिखें, और वह उसे लेकर झील में बहुत दूर बह जाती है; जादू की छड़ी से रेत पर वह लिखा जा सकता है जिसे छोड़ना है, और वह तब तक रहता है जब तक आप उसे उँगली से न मिटाएँ) और जंगल की पगडंडी (वह रात में खुलती है, और लालटेनों को छूने से दिन हो जाता है; बेंच पर बैठा जा सकता है, और बोर्ड को छूने पर वह पास आ जाता है – छह छोटे सवालों वाला तख़्ता जिन पर निशान लगाया जा सकता है)। बंद प्रवेश पर दिखता है कि कितनी चाबियाँ बाक़ी हैं। पगडंडी के आख़िर में एक चमकता द्वार झरने के पास योग तक ले जाता है – और वहाँ से ख़ुद झरने तक।",
