    dev_weather_preview_label: "प्रीव्यू – सिर्फ़ आपके अकाउंट में:",
    faq_a_ai_chat: "बबल पर टैप करें और चैट खुल जाएगी। चुनें कि क्या करना है – कैलेंडर के लिए कुछ, आपने क्या खाया, रेसिपी की फ़ोटो या नई तालिका – या बस लिख दें, सहायक खुद समझ जाएगा। 🎙️ पर टैप करके टाइप करने के बजाय बोला भी जा सकता है। कैलेंडर के लिए एक बार, हर हफ़्ते या हर दिन चुना जा सकता है। जवाब चैट में आता है, और वहां से कुछ और शुरू किया जा सकता है या कैलेंडर / खाया हुआ खोला जा सकता है।",
    faq_a_new_me_hall: "New Me एक जादुई जंगल के द्वार पर खुलता है, और वहाँ का हर प्रवेश एक जगह है: विशाल पेड़ में बना गोल दरवाज़ा गुप्त कमरे में ले जाता है, खोखला लट्ठा समुद्र के सामने वाले बरामदे तक, मशरूम वाला घर गिटार और डायरी तक, विलो का छोटा मेहराब साँस लेने के कमरे तक, विलो का बड़ा मेहराब जंगल की पगडंडी तक, और सीढ़ी वाला फूलों का मेहराब, तारों वाली छत खुलने के बाद, ऊपर छत तक ले जाता है। बंद प्रवेश पर ताला दिखता है। पगडंडी पर आपका किरदार Sky तैरता है, और चारों ओर खेल के बटन हैं: अगला मिशन, हफ़्ते की चुनौती, पूरे New Me वाला जादुई बैकपैक, दुनिया का नक्शा और टूल। ऊपर की चाबियों को छूने पर बताया जाता है कि चाबियाँ कैसे मिलती हैं।",
    faq_a_new_me_routine_meals: "जब New Me में भोजन तय हों और मेरी दिनचर्या में भी भोजन हों, तो New Me पूछता है कि क्या उन्हें छिपाकर उनकी जगह New Me के भोजन दिखाए जाएँ – ताकि कुछ भी दो बार न दिखे। फिर मेरी दिनचर्या New Me के भोजन उनके समय पर 💎 और ✓ के साथ दिखाती है; किसी भोजन के नाम पर टैप करने से दिनचर्या के ऊपर ही एक विंडो खुलती है, जिसमें दूसरा भोजन चुना जा सकता है या उसका समय बदला जा सकता है। कुछ भी मिटता नहीं: वे New Me की ⚙️ सेटिंग्स → दिनचर्या में भोजन से वापस आते हैं, या मेरी दिनचर्या के ⚙️ में “New Me के साथ सिंक” बंद करने से। सक्रिय New Me न होने पर वे अपने-आप वापस आ जाते हैं।",
    faq_a_room_computer: "यह एक छोटी चैट है जो “अब तक आपका दिन कैसा जा रहा है?” से शुरू होती है – अच्छा, व्यस्त या मुश्किल – और कदम-दर-कदम आपके साथ आगे बढ़ती है, आख़िर में एक छोटे मिशन तक (जिसे सीधे मेरा दिन में भी डाला जा सकता है)। जवाबों पर टैप किया जा सकता है या खुलकर लिखा जा सकता है – जो लिखा जाता है, वह सबसे नज़दीकी जवाब से जुड़ जाता है। “↩ वापस” एक कदम पीछे ले जाता है ताकि अलग जवाब दिया जा सके, और “नई चैट” किसी भी पल शुरुआत से शुरू करती है। व्यस्त या मुश्किल दिन के बाद उसी दिन बाद में कंप्यूटर पर लौटा जा सकता है: “फिर से यहां हूं...” बातचीत आगे बढ़ाता है। नीचे की हरी बत्ती कंप्यूटर को बंद और चालू करती है। सिर्फ़ चुनाव सहेजे जाते हैं, सिर्फ़ इसी डिवाइस पर और सिर्फ़ दिन के अंत तक।",
    faq_q_ai_chat: "सहायक से बात कैसे करें?",
