    nm_tour_lamps_title: "लैंप",
    pcx_a1_o1: "बस पूरा फ़ोकस रहा, मैंने फ़ोन देखा ही नहीं",
    pcx_a1_o2: "मैंने पहले से ही काम छोटे-छोटे कदमों में बांट लिए",
