    pcx_a1_q: "जो काम इंतज़ार कर रहे थे, उन पर टिक लगाने जैसा सुकून और कहीं नहीं! आज काम निपटाने में किस चीज़ ने फ़र्क डाला?",
    pcx_a1a_q: "फ़ोन फ़ोकस का दुश्मन नंबर एक है, इसलिए यह ध्यान भटकाने वाली चीज़ों पर बड़ी जीत है! यह एहसास कैसा था कि घंटों बीत गए और स्क्रॉल तक नहीं किया?",
