    pcx_c2_o2: "गुस्सा जो अब भी उबल रहा है",
    pcx_c2_q: "लोगों से टकराव या मुश्किल बातचीत एक भारी असर छोड़ जाती है जो पूरे दिन का सुकून बिगाड़ सकता है। इसमें सबसे ज़्यादा क्या खल रहा है?",
    pcx_c2a_q: "यह महसूस होना कि कोई देख या समझ नहीं रहा, बहुत तकलीफ़देह है। क्या इसे यहां शब्दों में बाहर निकालें?",
