    faq_a_dictation: "हाँ – झटपट नोट या नोटबुक के लिखने वाले पेज के कोने में 🎤 माइक्रोफ़ोन पर टैप करें और बोलें: शब्द बोलते-बोलते ऐप की भाषा में लिखे जाते हैं। रोकने के लिए फिर से टैप करें। पहली बार ब्राउज़र माइक्रोफ़ोन की अनुमति माँगता है। Chrome / Android और iPhone के Safari में काम करता है। कंप्यूटर पर माइक्रोफ़ोन और Chrome, Edge या Safari जैसा ब्राउज़र चाहिए – अगर कुछ कम है, तो संदेश ठीक-ठीक बताता है कि क्या।",
    faq_q_dictation: "क्या टाइप करने की जगह बोल सकते हैं?",
    faq_a_secret_room: "New Me के अंदर एक कमरा जो सिर्फ़ आपका है – एक विशाल पेड़ के अंदर बना घर। एक बार में एक दीवार दिखती है और तीरों (या स्वाइप) से घूमा जाता है। पहली चाबी 3 अलग-अलग दिनों में किसी भोजन पर ✓ के बाद मिलती है और दरवाज़ा खोलती है – और उसके साथ पूरा कमरा: कंप्यूटर, खेल, रिकॉर्ड प्लेयर, अंदर लाइब्रेरी वाला शेल्फ़ और बिल्ली। इसके बाद हर पूरी हुई चुनौती (हफ़्ते की चुनौती भी) एक चाबी देती है जो अगली जगह खोलती है: तारों वाली छत, समुद्र के सामने वाला बरामदा, गिटार और डायरी, साँस लेने का कमरा, योग के साथ जंगल की पगडंडी, झरना और छत पर एक सरप्राइज़ – और 8वीं चुनौती समुद्र से एक बोतल लाती है, जिसमें अतीत से आई चिट्ठी होती है। जब कुछ खुलता है, एक तीर वहाँ तक का रास्ता दिखाता है। खेल की मशीन के नीचे का छोटा दरवाज़ा भी खुलता है – फ़िलहाल उसके पीछे की अलमारी ख़ाली है। तारों वाली छत पर टैप किया गया तारा टूटते तारे की तरह गिरता है, और बिल्ली गद्दी पर बैठी होती है।",
