    sport_steps_week_label: "इस हफ़्ते",
    faq_a_reminders_one_place: "हर रिमाइंडर एक बार, एक ही जगह आता है। अगर ऐप आपके सामने खुला है (कंप्यूटर, iPad या फ़ोन पर), तो वह वहीं दिखता है; नहीं तो सूचना के रूप में सिर्फ़ फ़ोन पर आता है। कहीं भी '✅ हो गया, धन्यवाद!' या 'ठीक है!' दबाने से वह सभी डिवाइस पर बंद हो जाता है और दोबारा नहीं आता। 'अभी नहीं' उसे टाल देता है: वह हर 5 मिनट में फिर आता है, हर बार एक ही जगह। सूची में काम पर ✓ लगाना भी 'हो गया' माना जाता है। कंप्यूटर और टैबलेट पर भी सूचनाएं पाने के लिए सेटिंग्स > सूचनाएं में 'कंप्यूटर और टैबलेट पर भी' चालू करें।",
    faq_q_reminders_one_place: "रिमाइंडर सिर्फ़ एक बार और सिर्फ़ फ़ोन पर ही क्यों आता है?",
    reminder_all_devices_hint: "डिफ़ॉल्ट रूप से हर रिमाइंडर एक बार, एक ही जगह आता है: फ़ोन पर, या उस डिवाइस पर जिस पर ऐप आपके सामने खुला है। एक जगह 'हो गया' या 'ठीक है' दबाने से वह हर जगह बंद हो जाता है।",
    reminder_all_devices_label: "कंप्यूटर और टैबलेट पर भी",
    myday_water_info: "पानी के 8 मध्यम / छोटे गिलास औसतन लगभग 2 लीटर होते हैं",
    faq_a_good_things: "शाम को (18:00 से) तारीख़ के नीचे एक छोटा बटन दिखता है: आज हुई अधिकतम 3 अच्छी बातें लिखें – एक भी काफ़ी है। वे सेव हो जाती हैं, और 'पिछले दिन' में पहले लिखा हुआ दिखता है। 'आज रात नहीं' इसे कल तक छिपा देता है, और सेटिंग्स > पर्सनलाइज़ेशन और कैलेंडर में इसे पूरी तरह बंद भी कर सकते हैं।",
    faq_a_home_countdown: "कैलेंडर में किसी इवेंट पर ⭐ लगाएँ (इवेंट सूची में उसके पास वाला तारा)। अगले 100 दिनों में सबसे नज़दीकी तारे वाला इवेंट तारीख़ के नीचे दिखता है – '3 दिन बाकी · माँ का जन्मदिन', 'कल · …' या 'आज · …'। उस पर टैप करें तो कैलेंडर में उसी दिन पहुँच जाएँगे।",
    faq_a_home_streak: "यह गिनता है कि लगातार कितने दिन कम से कम एक ✓ रहा – मेरा दिन, मेरी दिनचर्या, मेरे लक्ष्य या New Me में कुछ भी। यह 2 दिन से दिखता है। आज अभी ✓ नहीं है तो सिलसिला टूटा नहीं – अभी पूरा दिन बाकी है। और अगर सिलसिला खत्म हो जाए, तो यह बस चुपचाप गायब हो जाता है, बिना किसी अपराधबोध के।",
    faq_a_home_weather: "सेटिंग्स > पर्सनलाइज़ेशन और कैलेंडर में 'होम स्क्रीन के आसमान में मौसम' चालू करें और स्थान की अनुमति दें। फिर होम स्क्रीन का आसमान आपकी जगह का असली मौसम दिखाता है – धूप (रात में चाँद और तारे), बादल, बारिश, बर्फ़, तूफ़ान या कोहरा – हर थीम में, लगभग हर 40 मिनट में अपडेट होते हुए। अनुमानित स्थान (लगभग 1 किमी तक गोल किया हुआ) सिर्फ़ आपके डिवाइस पर रहता है और हमारे सर्वर के ज़रिए MET Norway से जाँचा जाता है। यह डिफ़ॉल्ट रूप से बंद है। स्विच के नीचे लिखा होता है कि अभी बाहर मौसम कैसा है – जैसे ⛅ आंशिक बादल, इसीलिए आसमान में धूप और बादल दोनों दिखते हैं।",
