    faq_a_home_focus: "होम स्क्रीन के ऊपर ◎ पर टैप करें: अभी की एक चीज़ – इस घंटे जो चल रहा है, या आज की सूची की अगली चीज़ – एक बड़े ✓ और त्वरित नोट के अलावा सब छिप जाता है। ✓ के बाद अगली चीज़ आती है। ऊपर 'फ़ोकस मोड ✕' से सब वापस आ जाता है।",
    faq_a_home_search: "मेन्यू ☰ खोलें – खोज बिल्कुल ऊपर है। कम से कम 2 अक्षर लिखें: नतीजे आपके नोट्स, खरीदारी सूची, कैलेंडर, रेसिपी, नोटबुक (शीर्षक और पेज का टेक्स्ट), लक्ष्य, टेबल और किताबों से आते हैं, प्रकार के हिसाब से – किसी पर टैप करें और सीधे वहाँ पहुँचें।",
    faq_a_my_day: "'मेरा दिन' पहले के 'आज की एक झलक' और 'मेरी दिनचर्या' को एक टाइमलाइन पर ले आता है। होम स्क्रीन के नीचे दिखता है कि कितना हो गया, अभी या आगे क्या है (झटपट ✓ के साथ), और शीर्षक के पास +1 से एक गिलास पानी। उस पर टैप करें (या ऊपर स्वाइप करें) तो पूरा दिन खुलता है: ऊपर बिना समय वाली चीज़ें, फिर घंटे के हिसाब से सब कुछ – कैलेंडर के काम, इवेंट और मीटिंग, हफ़्ते के तय स्लॉट, आज की दिनचर्या, लक्ष्यों के छोटे कदम और New Me के भोजन – साथ में 'अभी' की लाइन। काम, दिनचर्या या मीटिंग और इवेंट से फ़िल्टर करें। यहाँ का ✓ हर जगह (मेरी दिनचर्या, मेरे लक्ष्य, कैलेंडर) वही ✓ है और कोने में एक डेज़ी खिलाता है। 'दिनचर्या बदलें' से 'मेरी दिनचर्या' खुलती है (मेनू में भी है), और '＋ आज के लिए जोड़ें' आज का एक काम जोड़ता है। \"मेरा दिन\" शीर्षक (या ऊपर की छोटी पट्टी) पर टैप करने से यह फिर बंद हो जाता है।",
