    faq_q_new_me_letter_gift: "अतीत से पत्र क्या है?",
    faq_a_new_me_challenges: "🏆 चुनौतियां में 20 चुनौतियां हैं: 10 बड़ी (जैसे बिना चीनी के 5 दिन, बिना कार्ब्स का एक हफ़्ता, या एक महीने में 4 किलो कम – हर दिन कैलोरी घाटा, वर्कआउट और बिना चीनी) और 10 मिनी – एक हफ़्ते की छोटी आदतें, जैसे बिना चीनी की दालचीनी वाली कॉफ़ी। चुनौती चुनने पर पूछा जाता है कि कब शुरू करें: आज, कल, अगले हफ़्ते या किसी और तारीख़ को। एक बड़ी और एक मिनी चुनौती साथ-साथ चल सकती हैं। चल रही चुनौती मेन्यू में सबसे ऊपर और मेरा दिन में दिखती है, दिन के लिए ✓ के साथ। चुनौती के हर हफ़्ते में एक छुट्टी का दिन (🍕) मिलता है जो उसे नहीं तोड़ता, और जिस दिन निशान नहीं लगा वह छुट्टी का दिन गिना जाता है – आज और कल, दोनों पर निशान लगाया जा सकता है। कुछ दिनों पर अपने-आप निशान लगता है: वर्कआउट ट्रैकिंग में 20 मिनट का वर्कआउट, या ✓ वाले मेन्यू के भोजन। हर चुनौती में एक ⓘ है कि ठीक-ठीक क्या गिना जाता है (जैसे कार्ब्स की पूरी सूची) – चुनौती के अंदर और मेरा दिन में उसके पास भी। इनके नीचे, 🌱 व्यक्तिगत विकास में एक हफ़्ते की 48 छोटी चुनौतियां हैं (ये 20 में नहीं गिनी जातीं) – देखें “हफ़्ते की चुनौती क्या है?”।",
