    faq_a_workout_calories: "हाँ। हर वर्कआउट के लिए बर्न हुई कैलोरी का अनुमान लगाया जाता है – प्रकार, अवधि और आपके हाल के वज़न से (दौड़ने और साइकिलिंग में दूरी डालने पर गति से भी)। यह वर्कआउट सूची और मासिक सारांश (बर्न) में दिखता है, और उस दिन के कैलोरी बजट में जुड़ता है: दैनिक भोजन ट्रैकर, कैलोरी और वजन मेट्रिक्स और New Me की रिंग में। यह अनुमान है, इसलिए ~ के साथ दिखता है।",
