    apptour_nb_inside_text: "हर जेब एक बाइंडर की तरह खुलती है, रंगीन डिवाइडर से एक जेब से दूसरी में जा सकते हैं। नोटबुक के पन्ने सच में पलटते हैं, और टेबल में वही कॉलम होते हैं जो आप चुनें।",
