    faq_a_recipe_to_preset: "हां। रेसिपी खोलें और '⭐ सहेजे गए भोजन में जोड़ें' पर टैप करें। नाम, प्रति सर्विंग कैलोरी (या कुल, अगर सर्विंग तय नहीं है) और सामग्री पहले से भरी होती है, सही श्रेणी के साथ – जांचें, जो चाहें बदलें और सेव करें। इसके बाद यह दैनिक भोजन ट्रैकर और क्विक ऐड 🍎 में एक टैप पर मिलेगा।",
    faq_q_recipe_to_preset: "क्या किसी रेसिपी को सहेजा गया भोजन बनाया जा सकता है?",
    recipe_add_to_presets_btn: "⭐ सहेजे गए भोजन में जोड़ें",
    faq_a_my_notebooks: "नोटबुक मेरे बैग की जेबों में रहती हैं, हर एक का कवर आपकी पसंद का – रंग, पैटर्न और स्टिकर। अंदर पन्ने क्रीम रंग के कागज़ के हैं और असली नोटबुक की तरह पलटते हैं: बगल में स्वाइप करें या नीचे की पट्टी में किसी पन्ने पर टैप करें, जहाँ ＋ नया पन्ना जोड़ता है – लाइन वाला (लिखने के लिए), ग्रिड वाला (गणित और स्केच के लिए), खाली (ड्रॉ करने के लिए) या चेकलिस्ट। ड्रॉइंग वाले पन्नों पर टूल पन्ने के नीचे तैरते हैं: पेन, मार्कर, चपटा मार्कर और इरेज़र, रंग और मोटाई के लिए रंग वाला गोला, पूर्ववत और स्टिकर। 🔍 खोज वाली विषय-सूची खोलता है, 🔖 उस पन्ने को चिह्नित करता है जहाँ नोटबुक खुलती है, और ⋯ में कवर और विवरण, पन्ने का नाम बदलना, ड्रॉइंग साफ़ करना और पन्ना हटाना है। मेरे बैग के ऊपर का ✅ काम कार्ड आपकी कामों की सूची खोलता है, बड़े कामों के लिए 🪄 स्मार्ट स्प्लिट के साथ। नोटबुक प्रीमियम का हिस्सा हैं; कामों की सूची मुफ़्त है।",
    faq_q_my_notebooks: "मेरी नोटबुक्स कैसे काम करती हैं?",
