    nm_story_weekly_title: "ज़्यादा हो गया? कोई तनाव नहीं",
    nm_story_after_text: "बस डेटाबेस में पका हुआ विकल्प चुनें – जैसे ‘पके हुए सफ़ेद चावल’, न कि ‘कच्चे चावल’।",
