    faq_a_goal_tasks_peek: "तीन तरह के: चल रही दिनों की चुनौती के दैनिक कार्य (जैसे 'कार्ब्स नहीं') – ये चुनौती पूरी होने तक हर दिन दिखते हैं, और वहां ✓ लगाने पर लक्ष्य में उस दिन पर भी टिक हो जाता है (और इसका उल्टा भी); 📅 लक्ष्य के शेड्यूल किए गए चरण – अपनी तारीख पर, और कैलेंडर में भी; और 👣 किसी भी दूसरे लक्ष्य का छोटा कदम – इसे लक्ष्य जोड़ते या संपादित करते समय तय करें (हर दिन, या हर हफ़्ते अपने चुने हुए दिन पर)। ये वही कदम हैं जो 'मेरे लक्ष्य' में सबसे ऊपर 'आज के छोटे कदम' में हैं, हर एक अपने लक्ष्य के आइकन के साथ। उस दिन दर्ज किया गया +1 छोटे कदम पर अपने-आप टिक कर देता है (और वजन भी, जब छोटा कदम ख़ुद वजन करना हो)।",
