    faq_a_goal_days_challenge: "मेरे लक्ष्य में ＋ पर टैप करें (या तैयार उदाहरण '🔥 8 दिन' पर), '📆 दिनों की चुनौती' चुनें, दिनों की संख्या दर्ज करें और हर दिन क्या करना है वह जोड़ें (जैसे '30 मिनट की सैर', 'अपने मेन्यू के अनुसार खाना')। हर दिन चुनौती के रास्ते के नीचे उस दिन के कार्यों पर टिक करें – जब सब पर टिक हो जाए तो वह दिन गिना जाता है, रास्ता एक पत्थर आगे बढ़ता है और आपकी 🔥 लगातार गिनती बढ़ती है (अगर दैनिक कार्य नहीं हैं तो एक ही बटन '✓ आज कर लिया' होता है)। किसी कार्य के बगल वाला 🔁 बटन उसे आपके चुने हुए घंटे पर मेरी दिनचर्या में जोड़ देता है: वहां टिक करने पर लक्ष्य में भी टिक हो जाता है, और इसका उल्टा भी। सामान्य लक्ष्य के चरण भी इसी तरह मेरी दिनचर्या में जोड़े जा सकते हैं।",
    faq_q_goal_days_challenge: "'8 दिन पैदल चलना और सेहतमंद खाना' जैसी चुनौती कैसे सेट करूं और उसे मेरी दिनचर्या से कैसे जोड़ूं?",
