    faq_a_app_tour: "टूर पहली बार ऐप में आने पर एक बार अपने-आप खुलता है। यह अपने हिस्सों से शुरू होता है – किसी हिस्से पर टैप करें और सीधे वहाँ पहुँचें – फिर ऐप का हर हिस्सा (होम स्क्रीन, AI सहायक और मेन्यू का हर आइटम) और सेटिंग्स के पाँच समूह दिखाता है, हर एक छोटी व्याख्या के साथ, और कुछ के अंदर भी झाँकता है (जैसे एक नमूना लक्ष्य पथ, बैग और Google Calendar)। \"जारी रखें\" आगे बढ़ाता है, \"वापस\" पीछे ले जाता है, \"यह हिस्सा छोड़ें\" अगले हिस्से पर ले जाता है और ✕ टूर बंद करता है। इसे कभी भी सेटिंग्स > सहायता और उपयोग > ऐप टूर से दोबारा देखें, और पिछली बार की जगह से जारी रखें। \"जारी रखें\" और \"वापस\" हमेशा स्क्रीन के नीचे एक ही जगह रहते हैं, और कंप्यूटर पर कीबोर्ड की तीर कुंजियाँ भी काम करती हैं।",
