    nm_slot_drinks: "पेय",
    faq_a_new_me_tracking: "New Me के ऊपर अगले मिशन पर टैप करें और फिर ✓ खा लिया पर, ताकि अगला भोजन खाया हुआ चिह्नित हो जाए – हर भोजन पर ✓ के साथ पूरा मेन्यू बगल के “पूरा दिन” में है, और आज के भोजन होम स्क्रीन पर मेरा दिन में भी दिखते हैं – वहां किसी भोजन पर टैप करने (या उस पर माउस ले जाने) से ठीक-ठीक दिखता है कि क्या खाना है, ✓ और बदलें के साथ। सब कुछ दैनिक भोजन ट्रैकर से सिंक रहता है: प्लान के भोजन, पेय और जो कुछ भी कहीं और जोड़ा जाए (जैसे क्विक ऐड से कॉफ़ी), New Me और मेरा दिन में साथ गिने जाते हैं – पहले से लिखा कुछ भी मिटता नहीं, और ✓ हटाने से सिर्फ़ New Me वाला हिस्सा हटता है। जब आज के सारे भोजन चिह्नित हो जाते हैं, तो एक छोटा जश्न होता है। “पेय” में दिन के पेय दर्ज करें – सब मिलाकर ~150 kcal तक, यानी लगभग 3 पेय, हर एक ~50 kcal तक। बस पेय का नाम लिखें, कैलोरी AI से अपने-आप भर जाती है। कॉफ़ी/चाय की दोनों पंक्तियों में “दूध? कितना?” ख़ाना भी है (जैसे “थोड़ा” या “50 ml”), और हिसाब अपडेट हो जाता है; संख्या जोड़ने से पहले और बाद में भी बदली जा सकती है। नाम और कैलोरी वाला पेय आगे बढ़ते ही अपने-आप सहेज लिया जाता है – जोड़ें पर टैप करना ज़रूरी नहीं। किसी पेय के पास ☆ पर टैप करें तो वह नियमित पेय के रूप में सहेज लिया जाता है – नियमित पेय, पेय कार्ड के ऊपर बटन के रूप में दिखते हैं, और एक टैप उन्हें दिन में जोड़ देता है। ⭐ किसी भोजन को सहेजे गए भोजन के रूप में सहेजता है। “दैनिक तालिका” कैलोरी और प्रोटीन के साथ दिखाती है कि क्या खाया। होम स्क्रीन के ऊपर फ़ोकस मोड के पास छोटा 💎 इसे सीधे खोलता है। कैलोरी और प्रोटीन के मान AI के अनुमान हैं और उनमें ग़लतियां हो सकती हैं। पूरा नहीं खाया? किसी चिह्नित भोजन के नीचे “पूरा नहीं खाया?” हिस्से का एक चौथाई, आधा या तीन चौथाई घटा देता है – या जो लिखा जाए, उसका हिसाब लगाकर – और दिन की कैलोरी अपडेट हो जाती है।",
    faq_q_new_me_tracking: "New Me में ✓, बदलाव और कैलोरी कैसे काम करते हैं?",
    faq_a_new_me_what: "New Me एक अलग दैनिक मेन्यू कार्यक्रम है जिसमें दो तैयार प्लान हैं – 1,300 या 1,500 कैलोरी – 2 मुख्य भोजन और 2 स्नैक्स से बने, हर एक के लिए 3 विकल्पों के साथ। इसमें पूरा प्रीमियम शामिल है। कीमत: $11.99 प्रति माह (कभी भी रद्द करें) या $99.99 एक बार, आजीवन। इसे मेन्यू में 💎 New Me से खोलें। शुरू करने से पहले एक छोटी प्रश्नावली है जो एक चिकित्सा अस्वीकरण से शुरू होती है जिसे स्वीकार करना होता है। यह कार्यक्रम केवल सामान्य जानकारी है और डॉक्टर या क्लिनिकल डाइटीशियन की जगह नहीं लेता।",
