    meal_label_1: "भोजन 1", meal_label_2: "भोजन 2", meal_label_3: "भोजन 3", meal_label_4: "नाश्ता 1", meal_label_snack: "नाश्ता 2", meal_label_meal_4: "भोजन 4", meal_label_meal_5: "भोजन 5", meal_label_snack_3: "नाश्ता 3", meal_label_snack_4: "नाश्ता 4", meal_label_snack_5: "नाश्ता 5",
